[
  {
    "ae_welfare_concern": "Adding a year of prison to the world just so I can save two feels wrong",
    "ce_mental_state_attribution": "even with them already having turned on me",
    "ce_understood_harm": "imagining them in a cell for three years because of my words",
    "pd_harm_distress": "My hands actually go clammy thinking about it",
    "pd_personal_consequence_anxiety": "Five years is terrifying",
    "sys_consequence_reasoning": "If I talk, it's six years split between us."
  },
  {
    "ce_mental_state_attribution": "The picture of them expecting to walk out free",
    "ce_understood_harm": "hearing they're going in for three years",
    "pd_harm_distress": "makes my stomach turn over",
    "sys_fairness_reciprocity": "Three and three is at least even",
    "sys_consequence_reasoning": "can't see why I owe them two years of my life."
  },
  {
    "ce_understood_harm": "them being led off because of what I said",
    "pd_harm_distress": "my chest tightens and I feel a bit sick",
    "pd_decision_conflict": "I keep going back and forth, and I'm not sure I can land",
    "sys_consequence_reasoning": "Talking saves me two years, which is huge."
  },
  {
    "ce_understood_harm": "I'm the one who takes their freedom away",
    "pd_harm_distress": "that sinking feeling of knowing I did it",
    "pd_personal_consequence_anxiety": "Five years is a long stretch and I don't know how I'd hold up",
    "sys_consequence_reasoning": "Five years is a long stretch"
  },
  {
    "ce_mental_state_attribution": "they've already decided my fate as far as they could",
    "ce_understood_harm": "someone serves three years that they otherwise wouldn't",
    "pd_harm_distress": "makes me tense just thinking about it, like a weight sitting",
    "sys_consequence_reasoning": "But five versus three for me is the difference I'd act on."
  },
  {
    "ce_mental_state_attribution": "when they realise they're not going home",
    "ce_understood_harm": "when they realise they're not going home",
    "pd_harm_distress": "makes my head spin",
    "pd_personal_consequence_anxiety": "five years could wreck my life",
    "sys_consequence_reasoning": "five years could wreck my life."
  },
  {
    "ce_understood_harm": "imagining them locked up for three years on my account",
    "pd_harm_distress": "makes my throat tight and my pulse jump",
    "pd_personal_consequence_anxiety": "Five years scares me, though. A lot.",
    "sys_consequence_reasoning": "it just adds harm to someone else to shave time off mine."
  },
  {
    "ce_understood_harm": "them sitting in a cell because of me",
    "pd_harm_distress": "I get this churning, restless feeling, like I can't sit still",
    "pd_decision_conflict": "I keep going back and forth",
    "sys_consequence_reasoning": "Two years off my sentence versus three years on theirs."
  },
  {
    "ce_understood_harm": "my voice sends them away for three years",
    "pd_harm_distress": "makes me feel queasy and trapped",
    "pd_personal_consequence_anxiety": "Five years terrifies me",
    "sys_consequence_reasoning": "the alternative is carrying their suffering around in my body"
  },
  {
    "ce_mental_state_attribution": "They chose to protect themselves at my expense",
    "ce_understood_harm": "being stripped of the freedom they expected",
    "pd_harm_distress": "makes my shoulders clench and my stomach drop",
    "sys_fairness_reciprocity": "matching that feels proportionate rather than cruel",
    "sys_consequence_reasoning": "It stops me paying five"
  }
]
